import wpilib
from wpimath import Pose2d

from commands3.button import CommandGamepad
from commands3.custom.greenlets import Command, Coroutine, Scheduler, Trigger

import constants as C
from mechanisms.intake import Intake
from mechanisms.shooter import Shooter
from mechanisms.swerve import SwerveDrive
from pose_estimator import PoseEstimator
from stubs.smart_motor import ExampleSmartMotorController


class Robot(wpilib.OpModeRobot):
    def __init__(self):
        super().__init__()
        self.swerve_drive = SwerveDrive()
        self.shooter = Shooter()
        self.intake = Intake()
        self.pose_estimator = PoseEstimator()
        self.controller = CommandGamepad(1)
        self.in_neutral_zone = Trigger(lambda: self.pose_estimator.in_zone(C.NEUTRAL_ZONE))
        self.scheduler = Scheduler.get_default()
        self.swerve_drive.set_default_command(self.swerve_drive.idle())
        self.shooter.set_default_command(self.shooter.idle())
        self.intake.set_default_command(self.intake.idle())

    def robot_periodic(self):
        self.pose_estimator.odometry_update(self.swerve_drive.get_gyro_heading(),
                                           self.swerve_drive.get_module_positions())
        self.scheduler.run()

    def simulation_periodic(self):
        for motor in ExampleSmartMotorController.registry.values():
            motor.simulate(0.02)

    def shoot_at(self, target_pose: Pose2d) -> Command:
        def body(co: Coroutine):
            co.await_(self.swerve_drive.aim_at(self.pose_estimator.get_estimated_pose,
                                                     target_pose))
            co.await_all(
                self.intake.agitate(),
                self.shooter.shoot_at_hub(lambda: target_pose.relative_to(
                    self.pose_estimator.get_estimated_pose()).translation().norm()))

        return Command.no_requirements(body).named(f"Robot.ShootAt[{target_pose}]")
